        [Console]::Error.WriteLine("workflow.sessionlog.setSessionTitle requires cached session metadata. $(Get-ReplRecoveryGuidance)")
        return $false
    }

    Set-ReplSessionStateValue -Key 'title' -Value $title | Out-Null

